exercises.starter:
function countByArchetype(cards) {
  // tally cards into a {archetype: count} object
}

exercises.solution:
function countByArchetype(cards) {
  const counts = {}
  for (const c of cards) {
    counts[c.archetype] = (counts[c.archetype] || 0) + 1
  }
  return counts
}

exercises.starter:
function cardsAtLevel(cards, level) {
  // return the names of cards at the given level, in order
}

exercises.solution:
function cardsAtLevel(cards, level) {
  return cards.filter(c => c.level === level).map(c => c.name)
}

exercises.starter:
function highAtkCards(cards, threshold) {
  // return names of cards with atk >= threshold, in order
}

exercises.solution:
function highAtkCards(cards, threshold) {
  return cards.filter(c => c.atk >= threshold).map(c => c.name)
}

exercises.starter:
function strongestCard(cards) {
  // return the name of the highest-atk card
}

exercises.solution:
function strongestCard(cards) {
  return cards.reduce((best, c) => (c.atk > best.atk ? c : best)).name
}

exercises.starter:
function avgAtkByArchetype(cards) {
  // map each archetype to its rounded average atk
}

exercises.solution:
function avgAtkByArchetype(cards) {
  const sums = {}
  const counts = {}
  for (const c of cards) {
    sums[c.archetype] = (sums[c.archetype] || 0) + c.atk
    counts[c.archetype] = (counts[c.archetype] || 0) + 1
  }
  const result = {}
  for (const a of Object.keys(sums)) {
    result[a] = Math.round(sums[a] / counts[a])
  }
  return result
}

exercises.starter:
function archetypeWithMostCards(cards) {
  // return the archetype with the most cards
}

exercises.solution:
function archetypeWithMostCards(cards) {
  const counts = {}
  for (const c of cards) {
    counts[c.archetype] = (counts[c.archetype] || 0) + 1
  }
  let best = null
  let bestCount = 0
  for (const a of Object.keys(counts).sort()) {
    if (counts[a] > bestCount) {
      bestCount = counts[a]
      best = a
    }
  }
  return best
}

exercises.starter:
function strongestPerArchetype(cards) {
  // map each archetype to the name of its highest-atk card
}

exercises.solution:
function strongestPerArchetype(cards) {
  const best = {}
  for (const c of cards) {
    if (!(c.archetype in best) || c.atk > best[c.archetype].atk) best[c.archetype] = c
  }
  const result = {}
  for (const a of Object.keys(best)) result[a] = best[a].name
  return result
}
